1	/**
2	 * Git worktree provisioning for coding projects. Each project gets its own
3	 * worktree + branch off one of the two known repos (Konrad's call: fixed
4	 * set of two, not arbitrary clone-any-repo) so parallel projects never
5	 * collide on files. Tasks within one project still share that project's
6	 * worktree — see lib/project-tick.ts for why that's an intentional v1
7	 * simplification (avoids needing real branch-merge logic).
8	 */
9	
10	import { run } from "./exec.ts";
11	import type { ProjectRepo } from "../db/projects.ts";
12	
13	const REPO_PATHS: Record<ProjectRepo, string> = {
14	  "ai-os": process.env.AI_OS_REPO_DIR ?? "/opt/forge-ai-os",
15	  "content-forge": process.env.CONTENT_FORGE_REPO_DIR ?? "/opt/content-forge",
16	};
17	
18	const WORKTREE_ROOT =
19	  process.env.PROJECT_WORKTREE_ROOT ?? "/opt/ai-os/workspace/projects";
20	
21	const UUID_RE =
22	  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
23	
24	export interface WorkspaceInfo {
25	  workspace_dir: string;
26	  work_branch: string;
27	}
28	
29	/** Idempotent: safe to call again for a project that already has a
30	 *  worktree (e.g. after an executor restart) — returns the existing one. */
31	export async function provisionWorkspace(project: {
32	  id: string;
33	  repo: ProjectRepo;
34	  base_branch: string;
35	}): Promise<WorkspaceInfo> {
36	  if (!UUID_RE.test(project.id)) {
37	    throw new Error(`refusing to provision workspace for non-uuid id: ${project.id}`);
38	  }
39	  const repoPath = REPO_PATHS[project.repo];
40	  if (!repoPath) throw new Error(`unknown project repo: ${project.repo}`);
41	
42	  const workBranch = `project/${project.id.split("-")[0]}`;
43	  const workspaceDir = `${WORKTREE_ROOT}/${project.id}`;
44	
45	  const existing = await run(
46	    `git -C "${repoPath}" worktree list --porcelain`,
47	    10_000,
48	  );
49	  if (existing.ok && existing.stdout.includes(`worktree ${workspaceDir}`)) {
50	    return { workspace_dir: workspaceDir, work_branch: workBranch };
51	  }
52	
53	  await run(`mkdir -p "${WORKTREE_ROOT}"`, 5_000);
54	
55	  // Fetch the base branch so the worktree starts from a current commit.
56	  // Non-fatal if it fails (e.g. detached/offline repo) — fall back to
57	  // whatever the local base_branch ref already points at.
58	  const fetch = await run(
59	    `git -C "${repoPath}" fetch origin ${project.base_branch}`,
60	    60_000,
61	  );
62	  const startPoint = fetch.ok
63	    ? `origin/${project.base_branch}`
64	   
